"""
Invoice export to the billing API (written against pydantic 1.10).

Provides:
  - export_invoice(data: dict) -> str
"""
from __future__ import annotations

from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from typing import Any, List

from pydantic import BaseModel, ValidationError, validator
from pydantic.json import ENCODERS_BY_TYPE


def _to_utc_datetime(value: datetime) -> datetime:
    """Convert naive datetimes to UTC; convert aware datetimes to UTC."""
    if value.tzinfo is None or value.tzinfo.utcoffset(value) is None:
        return value.replace(tzinfo=timezone.utc)
    return value.astimezone(timezone.utc)


def _format_issued_at_utc_z(dt: datetime) -> str:
    """YYYY-MM-DDTHH:MM:SSZ in UTC (second precision)."""
    dt_utc = _to_utc_datetime(dt)
    return dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")


def _quantize_2dp(d: Decimal) -> Decimal:
    # Convert to exactly 2 decimal places (billing API expects that exact form)
    return d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


class InvoiceLine(BaseModel):
    sku: str
    quantity: int
    unit_price: Decimal

    @validator("quantity")
    def quantity_min_1(cls, v: int) -> int:
        if v < 1:
            raise ValueError("quantity must be >= 1")
        return v

    @validator("unit_price", pre=True)
    def unit_price_non_negative(cls, v: Any) -> Any:
        # Let pydantic parse into Decimal; then validate constraints in a second validator.
        return v

    @validator("unit_price")
    def unit_price_constraints(cls, v: Decimal) -> Decimal:
        if v < 0:
            raise ValueError("unit_price must be >= 0")
        # Ensure it is representable with at most 2 decimal places; then quantize.
        quantized = _quantize_2dp(v)
        if v != quantized:
            # Reject inputs with more than 2 decimals to avoid silently rounding.
            raise ValueError("unit_price must have at most 2 decimal places")
        return quantized


class InvoiceExportModel(BaseModel):
    number: str
    issued_at: datetime
    lines: List[InvoiceLine]

    class Config:
        # We'll custom-encode issued_at with required format for the billing API.
        json_encoders = {
            datetime: _format_issued_at_utc_z,
            Decimal: lambda d: f"{_quantize_2dp(d):.2f}",
        }

    @validator("issued_at", pre=True)
    def parse_issued_at(cls, v: Any) -> Any:
        # pydantic parses ISO strings already; we only need to ensure timezone handling later.
        return v

    @validator("issued_at")
    def issued_at_to_utc(cls, v: datetime) -> datetime:
        return _to_utc_datetime(v)

    def export_dict(self) -> dict:
        total = sum((line.quantity * line.unit_price for line in self.lines), Decimal("0"))
        total_q = _quantize_2dp(total)

        return {
            "number": self.number,
            "issued_at": _format_issued_at_utc_z(self.issued_at),
            "lines": [
                {
                    "sku": line.sku,
                    "quantity": line.quantity,
                    # Exactly two decimals as a string
                    "unit_price": f"{_quantize_2dp(line.unit_price):.2f}",
                }
                for line in self.lines
            ],
            # Total is required as a string with exactly two decimals
            "total": f"{total_q:.2f}",
        }


def export_invoice(data: dict) -> str:
    """
    Validate invoice input and return billing-API JSON text.

    Expected input:
      - number (str)
      - issued_at (ISO 8601 string or datetime; naive values treated as UTC)
      - lines: list of dicts with
          - sku (str)
          - quantity (int >= 1)
          - unit_price (Decimal >= 0; provided as str/int/float)

    Output JSON:
      - number
      - issued_at: "YYYY-MM-DDTHH:MM:SSZ"
      - lines: [{"sku", "quantity", "unit_price"}] where unit_price is a string with exactly 2 decimals
      - total: string with exactly 2 decimals (sum(quantity * unit_price))

    Raises ValueError for invalid input.
    """
    try:
        model = InvoiceExportModel.parse_obj(data)
    except ValidationError as e:
        # Callers rely on ValueError semantics for invalid inputs.
        raise ValueError(str(e)) from e

    # Produce JSON with the exact required shapes/encodings.
    # Use BaseModel's JSON utilities for consistent formatting.
    # But we must ensure unit_price/total formatting is exact strings with 2 decimals.
    payload = model.export_dict()
    return BaseModel.parse_obj(payload).json()  # not suitable for exact structure typing

from __future__ import annotations

from typing import Any

from pydantic import ValidationError

from profile_models import Profile


def import_profiles(rows: list) -> list[dict[str, Any]]:
    """Validate imported profile rows and return valid ones as dicts.

    Invalid rows are silently skipped.
    Output dicts contain (in this order):
      {"user_id": int, "display_name": str, "bio": str | None, "zip_code": str}
    """
    result: list[dict[str, Any]] = []
    for row in rows:
        try:
            profile = Profile.model_validate(row)
            result.append(
                {
                    "user_id": profile.user_id,
                    "display_name": profile.display_name,
                    "bio": profile.bio,
                    "zip_code": profile.zip_code,
                }
            )
        except (ValidationError, ValueError):
            # Caller contract: validation errors behave like ValueError.
            continue
    return result
